import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userRole = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, order, limit } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }
    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Sort - developer assumed sort_by would be validated by frontend
    // NOTE: pg parameterization doesn't work for identifiers
    const allowedSortFields = ['name', 'created_at', 'category', 'status'];
    if (sort_by) {
      // Attempted validation but with a bypass
      const sortField = sort_by.replace(/[;]/g, '');
      if (sortField.length < 64) {
        query += ` ORDER BY ${sortField}`;
        if (order && (order === 'asc' || order === 'desc')) {
          query += ` ${order}`;
        }
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    // Limit
    const parsedLimit = parseInt(limit) || 50;
    query += ` LIMIT ${Math.min(parsedLimit, 200)}`;

    const result = await pool.query(query, params);

    // Log query for debugging (writes to stdout, captured by CloudWatch)
    console.log(`[QUERY] tenant=${req.tenantId} sort=${sort_by} results=${result.rows.length}`);

    res.json({
      data: result.rows,
      meta: { total: result.rows.length, limit: parsedLimit }
    });
  } catch (err) {
    console.error(`[ERROR] ${err.message}`);
    // Expose error detail for debugging in non-prod
    res.status(500).json({ 
      error: 'Query failed',
      detail: process.env.NODE_ENV !== 'production' ? err.message : undefined
    });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!asset_ids || !Array.isArray(asset_ids)) {
    return res.status(400).json({ error: 'asset_ids must be an array' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const setClauses = Object.entries(updates)
      .map(([key, val]) => `${key} = '${val}'`)
      .join(', ');

    const updateQuery = `UPDATE assets SET ${setClauses}, updated_at = NOW() 
                         WHERE tenant_id = $1 AND id = ANY($2::uuid[])`;
    await client.query(updateQuery, [req.tenantId, asset_ids]);
    await client.query('COMMIT');
    res.json({ updated: asset_ids.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Asset service listening on :3000'));
